_CRITERIA_SHA = "bc2e0b053ff83c04bf2f44c73f961288101919a7c0cbf41c643ef3b53a075535"

def build():
    data=json.loads(zlib.decompress(base64.b85decode(_PAYLOAD)).decode())
    entries={n:base64.b64decode(v,validate=True) for n,v in data.items()}
    if hashlib.sha256(entries['references/criterios.md']).hexdigest()!=_CRITERIA_SHA:
        raise RuntimeError('catalog content corrupted')
    ids=set(re.findall(rb'^\|\s*([A-Z]+-\d{2})\s*\|',entries['references/criterios.md'],flags=re.M))
    if len(ids)!=77:
        raise RuntimeError('expected 77 catalog IDs')
    manifest=''.join(f'{hashlib.sha256(entries[n]).hexdigest()}  {n}\n' for n in sorted(entries))
    entries['MANIFEST.sha256']=manifest.encode('utf-8')
    root=Path('refactor-codebase')
    for name, blob in entries.items():
        dest=root/name
        dest.parent.mkdir(parents=True,exist_ok=True)
        dest.write_bytes(blob)
    with zipfile.ZipFile('refactor-codebase.zip','w',zipfile.ZIP_DEFLATED,compresslevel=9) as z:
        for name,blob in sorted(entries.items()):
            inf=zipfile.ZipInfo('refactor-codebase/'+name,(2026,1,1,0,0,0))
            inf.compress_type=zipfile.ZIP_DEFLATED
            inf.external_attr=(stat.S_IFREG|0o644)<<16
            z.writestr(inf,blob,compress_type=zipfile.ZIP_DEFLATED,compresslevel=9)
    print('Created refactor-codebase/ and refactor-codebase.zip')
    print('Catalog:',len(ids),'active criteria; SHA256:',_CRITERIA_SHA)
    print('Archive SHA256:',hashlib.sha256(Path('refactor-codebase.zip').read_bytes()).hexdigest())

if __name__=='__main__':
    build()